 for(const ev of events){if(!ev.event_id||ids.has(ev.event_id)||!(known.has(ev.step_id)||(binding?.added_steps||[]).some(x=>x.id===ev.step_id&&/^BS-[0-9]{3,}$/.test(x.id||'')))||ev.application_id!==raw.application_id||ev.target_version!==raw.target_version||ev.process_version!==def.version||ev.definition_sha256!==def.source_sha256||!ev.item_key||!ev.actor||!ev.at||!Number.isInteger(ev.revision)||ev.revision<1)errors.push('Sự kiện sai mã/phiên hoặc thiếu nguồn.');ids.add(ev.event_id);}
