  const timingOK=ev&&(!ev.completed_at||(Number.isFinite(Date.parse(ev.started_at))&&Number.isFinite(Date.parse(ev.completed_at))&&Date.parse(ev.completed_at)>=Date.parse(ev.started_at)))&&(!('duration_ms' in ev)||(Number.isFinite(ev.duration_ms)&&ev.duration_ms>=0));
