 return {...x,lifecycle_code:phase,lifecycle:p.states[phase],source_revision:version?'SHA256 '+version.slice(0,12):'Chưa ghim phiên nguồn',revision:(m.contract_revision?'HĐ '+m.contract_revision:'Chưa khai hợp đồng')+' · nâng '+(m.baseline_ref?upgrades.length+' lần từ P34':'chưa thống kê'),last_check:tested?'TEST đạt · '+(x.checked.job_id||x.checked.evidence_ref):stale?'Kết quả phiên cũ':x.checked?'Kiểm chưa đạt':'Chưa kiểm được phiên này',next_action:(m.blocker?m.blocker+' → ':'')+(m.next_action||step),keeper:m.owner||x.owner||'Host tools-quy-trinh · điều phối',gpt_review:g.label,claude_review:c.label,binding,review_records:reviews,change_records:history,use_basis:consensus?'Đồng thuận hai hãng':ownerAllows?'Owner cho áp thử P34, không lấy thiếu Claude làm điểm dừng':'Chưa đủ căn cứ công bố dùng được',acceptance_scope:m.acceptance_scope||'Chưa chốt phạm vi dùng lại',memory:m};
