function toolRows(r){
 const p=r.tool_registry?.audit_projection,known=(r.tool_registry?.records||[]).map(x=>{const checked=p?.last_checks?.find(y=>y.id===x.id),proof=checked?(checked.sha256!==x.sha256?'Có kiểm phiên trước · cần kiểm lại':checked.exit_code===0?'Đã đạt TEST · mã công cụ khớp':'Kiểm TEST chưa đạt'):'Đã đăng ký · chưa có biên nhận đối chiếu';return {...x,record_id:x.id,name:x.name||x.id,group:'Bộ kiểm QTTH',full_purpose:x.purpose,purpose:(r.tool_registry.reuse_needs||[]).filter(n=>n.tool_ids.includes(x.id)).map(n=>n.need).join(' · ')||x.name,target_version:x.sha256,state:proof+(x.runtime_binding?.state==='ENFORCED_FILE_SCOPE'?' · chốt ghi bật cho 1 tệp kho thử':' · chỉ đọc'),checked,evidence_ref:checked?.evidence_ref,verify:x.kind==='RUNNER'?x.verify:x.argv.join(' ')};});
 const ids=new Set(known.map(x=>x.record_id));
 const found=[...(p?.dot_inventory||[]),...(p?.script_inventory||[])].map(x=>{if(ids.has(x.id))throw Error('DUPLICATE_TOOL:'+x.id);ids.add(x.id);const m=(r.tool_registry.memory||[]).find(y=>y.tool_id===x.id)||{},proof=m.last_verified_check,checked=proof&&typeof m.acceptance_scope==='string'&&m.acceptance_scope.trim()&&proof.scope===m.acceptance_scope&&typeof proof.evidence_ref==='string'&&proof.evidence_ref.trim()?proof:null;return {...x,record_id:x.id,target_version:x.sha256,state:checked?'Có biên nhận kiểm · xem phiên và hiệu lực':'Đã tìm thấy · chưa kiểm chạy',verify:'Đọc hợp đồng, quyền và phạm vi trước khi dùng',owner:'Nguồn DOT trên VPS',case_set:checked?.case_set||'Chưa đối chiếu',checked,evidence_ref:checked?.evidence_ref||p.evidence_ref};});
 return [...known,...found].map(x=>lifecycle(r,x));
}
function providerRows(r,legacy=[]){
 const p=r.tool_registry?.audit_projection,by=new Map((p?.by_action||[]).map(x=>[x.action,x]));
 return [...legacy.map(x=>({...x,record_id:x.id,group:'Phương pháp',purpose:x.purpose||x.name,state:'Phương pháp · chưa tự động hóa',provider:'Nguồn Master Tool hiện hữu'})),...(r.tool_registry?.provider_tools||[]).map(x=>{const u=by.get(x.id),external=(p?.external_receipts||[]).filter(y=>y.action===x.id);return {...x,record_id:x.id,name:x.id,group:x.provider,purpose:x.purpose,usage:u,state:external.length?'Có biên nhận nền tảng':u?.complete_receipts?'Có biên nhận gateway':u?'Có dấu vết gọi · thiếu kết quả/phiên':'Chưa có biên nhận trong phạm vi rà',evidence_ref:external[0]?.evidence_ref||p?.evidence_ref||'Chưa ghi',external_receipts:external};})].map(x=>lifecycle(r,x));
}
function reuseMatrix(r){const tools=new Map([...toolRows(r),...providerRows(r)].map(x=>[x.record_id,x]));return (r.tool_registry?.reuse_needs||[]).map(x=>({...x,tools:x.tool_ids.map(id=>{const t=tools.get(id);if(!t)throw Error('UNKNOWN_REUSE_TOOL:'+id);return t;}),gap:x.tool_ids.length?'Kiểm đúng phạm vi và phiên trước mỗi lượt':'Chưa có công cụ/bằng chứng đủ để khép kín'}));}
function toolView(r,it){const x=it.metadata,e=escapeHtml,p=r.tool_registry.audit_projection;return {title:x.name||x.record_id,source:'Nguồn dùng lại · bằng chứng theo phạm vi',fullWidth:true,interactive:true,html:'<section style="line-height:1.7;overflow-wrap:anywhere"><p><b>'+e(x.full_purpose||x.purpose||x.name)+'</b></p><p>'+e(x.state)+'</p><dl>'+[['Mã',x.record_id],['Tiến trình',x.lifecycle],['Phiên nguồn',x.source_revision],['Phiên hợp đồng / nâng cấp',x.revision],['Phạm vi dùng lại',x.acceptance_scope],['Căn cứ áp dụng',x.use_basis],['Việc tiếp',x.next_action],['Người giữ',x.keeper],['GPT duyệt',x.gpt_review],['Claude duyệt',x.claude_review],['Lịch sử nâng cấp',x.change_records?.length?x.change_records:'Chưa có lần nâng được ghi'],['Phiếu duyệt có căn cứ',x.review_records?.length?x.review_records:'Chưa có phiếu'],['Nhà cung cấp / nhóm',x.provider||x.group],['Nguồn',x.path||x.source||x.url],['Phiên / hash',x.sha256||x.version_policy],['Cách dùng / kiểm',x.verify||x.version_policy],['Điều kiện',x.preconditions],['Đầu vào',x.input],['Đầu ra',x.output],['Bằng chứng',x.evidence_ref||p?.evidence_ref],['Lượt kiểm gần nhất (không nghiệm thu đầu vào mới)',x.checked],['Dấu vết sử dụng',x.usage?JSON.stringify(x.usage):'Xem bản kiểm kê theo lượt; không suy từ có tệp thành đã chạy'],['Phạm vi cưỡng chế ghi',x.runtime_binding?JSON.stringify(x.runtime_binding):null]].filter(a=>a[1]).map(a=>'<dt><b>'+e(a[0])+'</b></dt><dd style="margin-left:0">'+e(typeof a[1]==='string'?a[1]:JSON.stringify(a[1]))+'</dd>').join('')+'</dl><p>Tra trước → dùng lại → thiếu mới bổ sung. Không tự chạy hàng loạt công cụ tìm thấy.</p>'+(x.url&&/^https?:|^\.\//.test(x.url)?'<p><a href="'+e(x.url)+'" target="_blank" rel="noopener">Mở hướng dẫn nguồn ↗</a></p>':'')+'</section>'};}
